// --- render-bus topics ---------------------------------------------------
// The naming grammar of the owner -> subscriber bus. Emitted rather than spelled
// on each side: two spellings of a topic is two buses. URLabRenderBusTopic
// builds and parses against these; Python has the same pair.
namespace RenderBusTopic
{
	// The always-published transform tier; asking for nothing lands here.
	inline const TCHAR* Lean = TEXT("render");
	// Root of every negotiated topic. NOT under Lean, and Lean not under it:
	// ZMQ matches subscriptions by prefix, so nesting would deliver the tier to
	// every lean subscriber. The trailing separator on a built topic is load-bearing
	// for the same reason -- without it "m1" is a prefix of "m10".
	inline const TCHAR* TieredRoot = TEXT("debug/");
	inline constexpr int32 TieredRootLen = 6;
}

// --- op declarations -----------------------------------------------------
// The op registry's ReplyFields / RequiredFields, emitted rather than typed
// out at each Reg() site. A Reg() site used to carry its own literal list,
// which is a second hand-written copy of the schema and rotted the moment a
// handler was rewritten: render_hello went on declaring mjb / xml /
// broadcasting long after they left the wire. Reg() now looks the op up here.
//
// An op the schema does not describe is ABSENT from this table on purpose,
// keeps the literals at its Reg() site, and is counted by
// URLab.Wire.OpDeclarationCoverage so the remainder stays visible.
namespace Decl
{
struct FOpFields
{
	const TCHAR* Op;
	const TCHAR* const* Reply;
	int32 ReplyNum;
	const TCHAR* const* Required;
	int32 RequiredNum;
};

namespace Fields
{
}

inline const FOpFields All[] = {
};
inline constexpr int32 Count = 0;

/** The schema's declaration for an op, or nullptr when the schema does not
 *  describe it -- in which case the Reg() site's own list stands. */
inline const FOpFields* Find(const TCHAR* Op)
{
	for (int32 i = 0; i < Count; ++i)
	{
		if (FCString::Strcmp(All[i].Op, Op) == 0)
		{
			return &All[i];
		}
	}
	return nullptr;
}
} // namespace Decl

